cat <<'EOF' > app.js
import {run} from './interpreter.js';import {examples} from './examples.js';
const app=document.querySelector('#app');const saved=(k,d)=>{try{return localStorage.getItem(k)||d}catch{return d}};let mode='2d',page='studio',theme=saved('logo-theme','system'),source=saved('logo-draft-2d',examples[0].source),segments=[],fullResult=null,visible=0,timer=null,running=false,paused=false,lineNow=0,scale=1,offset=[0,0],camera={yaw:.65,pitch:.35,zoom:1,panX:0,panY:0},drag=null,selectedTask=0;
const tasks=[{title:'Kwadrat',desc:'Narysuj kwadrat o boku 80. Użyj czterech równych boków i czterech kątów prostych.',src:'powtorz 4 [np 80 pw 90]',mode:'2d'},{title:'Trójkąt',desc:'Narysuj trójkąt równoboczny o boku 100.',src:'powtorz 3 [np 100 pw 120]',mode:'2d'},{title:'Zygzak',desc:'Narysuj pięć równych odcinków długości 30, skręcając naprzemiennie w prawo i lewo.',src:'powtorz 5 [np 30 pw 60 np 30 lw 60]',mode:'2d'},{title:'Schodki w górę',desc:'W 3D narysuj cztery stopnie: po każdym poziomym odcinku 25 jednostek unieś nos o 90°, przejdź 15 i wróć do poziomu.',src:'powtorz 4 [np 25 gora 90 np 15 dol 90]',mode:'3d'},{title:'Dom z dachem',desc:'Narysuj w 2D dom: kwadrat o boku 70 i trójkątny dach na jego górnym boku.',src:'kolor \"#c1763d\"\\npowtorz 4 [np 70 pw 90]\\nnp 70 lw 120 np 70 lw 120 np 70',mode:'2d'}];
function themeApply(){const t=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;document.documentElement.dataset.theme=t}
themeApply();
function esc(s){return s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}
function render(){app.innerHTML="'`<div class="shell"><header class="topbar"><div class="brand"><span class="brandmark">⌁</span>Logomocja</div><nav class="topnav" aria-label="Nawigacja"><button class="${page==='"'studio'?'active':''}\" data-page=\"studio\">Pracownia</button><button class=\""'${page==='"'challenges'?'active':''}\" data-page=\"challenges\">Wyzwania</button><button class=\""'${page==='"'reference'?'active':''}\" data-page=\"reference\">Język Logo</button><button class=\"theme-toggle\" id=\"theme\" aria-label=\"Zmień motyw\" title=\"Motyw: "'${theme}">${themeApplyIcon()}</button></nav></header>${page==='"'studio'?studio():page==='challenges'?challengePage():referencePage()}</div><div id=\"toast\" class=\"toast hidden\" role=\"status\"></div>"'`;
app.querySelectorAll('"'[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});document.querySelector('#theme').onclick=()=>{theme=theme==='system'?'dark':theme==='dark'?'light':'system';localStorage.setItem('logo-theme',theme);themeApply();render()};if(page==='studio')bindStudio();if(page==='challenges')bindChallenges();}
