function studio(){return "'`<main class="workspace"><div class="intro"><div><div class="eyebrow">Polska pracownia programowania</div><h1>Pomysł w ruch, żółwiu.</h1><p>Napisz program. Zobacz, dokąd zaprowadzi Cię żółw.</p></div><div><button id="share">↗ Udostępnij</button></div></div><section class="layout"><article class="panel editor-panel"><div class="panel-head"><div><div class="panel-title">Program</div><div class="panel-sub">Twój szkic zapisuje się automatycznie</div></div><select id="examples" class="select" aria-label="Wczytaj przykład"><option value="">Wczytaj przykład…</option>${examples.map((x,i)=>`<option value="${i}">${x.name} · ${x.mode.toUpperCase()}</option>`).join('"'')}</select></div><div class=\"toolbar\"><button id=\"run\" class=\"primary runbtn\">▶ Uruchom</button><button id=\"step\" class=\"iconbtn\" title=\"Wykonaj krok (F8)\">▹ Krok</button><button id=\"pause\" class=\"iconbtn\" title=\"Pauza (F9)\">Ⅱ</button><button id=\"reset\" class=\"iconbtn\" title=\"Resetuj (Ctrl+Enter)\">↺</button><span class=\"spacer\"></span><label for=\"speed\" class=\"panel-sub\">Tempo</label><input id=\"speed\" class=\"speed\" type=\"range\" min=\"1\" max=\"10\" value=\"6\" aria-label=\"Tempo animacji\"></div><div class=\"editwrap\"><pre class=\"codepaint\" aria-hidden=\"true\" id=\"paint\"></pre><textarea class=\"codeinput\" id=\"editor\" aria-label=\"Edytor programu Logo\" spellcheck=\"false\" autocapitalize=\"off\"></textarea></div><div class=\"diagnostic\" id=\"diagnostic\" aria-live=\"polite\">Gotowy. Napisz program lub wybierz przykład.</div><div class=\"editor-foot\"><span>⌘/Ctrl ↵ uruchom · F8 krok · F9 pauza · Esc reset</span><span id=\"chars\">0 znaków</span></div></article><article class=\"panel canvas-panel\"><div class=\"panel-head\"><div><div class=\"panel-title\">Płótno</div><div class=\"panel-sub\" id=\"canvasSub\">Płaszczyzna XY · początek (0, 0)</div></div><div class=\"canvas-toolbar\"><div class=\"mode-switch\"><button data-mode=\"2d\">2D</button><button data-mode=\"3d\">3D</button></div><button class=\"iconbtn\" id=\"fit\" aria-label=\"Dopasuj rysunek\">Dopasuj</button><button class=\"iconbtn\" id=\"png\" aria-label=\"Pobierz rysunek jako PNG\">PNG ↓</button></div></div><div class=\"stage\"><canvas id=\"canvas\" aria-label=\"Płótno rysunku żółwia\"></canvas><div class=\"stage-note\" id=\"stageNote\">Przeciągnij, aby przesunąć · kółko, aby przybliżyć</div></div><div class=\"canvas-foot\"><span id=\"segcount\">0 odcinków</span><span class=\"turtle-status\" id=\"tstatus\">● x 0 · y 0 · z 0</span></div></article></section><section class=\"below\"><article class=\"panel card\"><h2>Gotowe na start</h2><p>Wybierz program i zobacz, jak działa. Każdy przykład możesz swobodnie zmieniać.</p><div class=\"example-list\">"'${examples.map((x,i)=>`<button class="example-chip" data-example="${i}">${x.name}</button>`).join('"'')}</div></article><article class=\"panel card\"><h2>Skróty klawiszowe</h2><p><span class=\"shortcut\">Ctrl/⌘ + Enter</span> uruchom &nbsp; <span class=\"shortcut\">F8</span> krok &nbsp; <span class=\"shortcut\">F9</span> pauza &nbsp; <span class=\"shortcut\">Esc</span> reset</p><p style=\"margin-top:10px\">Wyniki pracy zostają w tej przeglądarce. Bez konta i bez wysyłania danych.</p></article></section></main>"'`}
function challengePage(){return `<main class="workspace"><div class="intro"><div><div class="eyebrow">Ćwiczenia praktyczne</div><h1>Małe zadania, wielkie pomysły.</h1><p>Sprawdź swój program automatycznie. Ukończenie zapisujemy na tym urządzeniu.</p></div></div><div class="challenge-layout"><div class="task-list">${tasks.map((t,i)=>`<button class="task-item ${i===selectedTask?'"'active':''}\" data-task=\""'${i}"><strong>${localStorage.getItem('"'challenge-'+i)==='yes'?'✓ ':''}"'${t.title}</strong><span>${t.mode.toUpperCase()} · zadanie ${i+1}</span></button>`).join('"'')}</div><article class=\"panel taskbox\"><div class=\"eyebrow\">Wyzwanie "'${selectedTask+1} z ${tasks.length}</div><h2>${tasks[selectedTask].title}</h2><p class="task-desc">${tasks[selectedTask].desc}</p><textarea class="task-code" id="taskCode" aria-label="Twój program do wyzwania">${esc(localStorage.getItem('"'challenge-src-'+selectedTask)||tasks[selectedTask].src)}</textarea><div style=\"display:flex;gap:8px;margin-top:12px\"><button class=\"primary\" id=\"checkTask\">Sprawdź rysunek</button><button id=\"tryTask\">Uruchom w pracowni</button></div><div id=\"taskResult\" class=\"task-result\" aria-live=\"polite\">Wyzwanie sprawdza kształt, położenie i liczbę narysowanych odcinków.</div></article></div></main>"'`}
